[CmdletBinding(SupportsShouldProcess)]param();$TaskName='E.X Market Radar - MOI Latest Refresh';if(Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue){if($PSCmdlet.ShouldProcess($TaskName,'Remove scheduled task')){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false};[pscustomobject]@{taskName=$TaskName;removed=$true}|ConvertTo-Json}else{[pscustomobject]@{taskName=$TaskName;removed=$false;safeMessage='Scheduled task is not installed.'}|ConvertTo-Json}
